#pragma once

// Shared icon assets for every page the adaptor serves.
//
//   PAGE_ICON_CSS  styling for inline icons — used by all pages
//   MAIN_SPRITE    the 24 icons used by the main UI (webpage.h)
//   PAGE_SPRITE    the 10 icons used by the pages built in webui.cpp
//                  (MQTT config, MQTT saved/error, MQTT reset, WiFi reset,
//                   factory reset)
//
// Two sprites rather than one: a sprite is sent with every response that
// uses it, so the small confirmation pages should not have to carry the
// main UI's full icon set. The cost is that refresh-alert and smart-home
// appear in both.
//
// These are macros rather than variables so they can be pasted into the
// pages' raw string literals by adjacent-literal concatenation at compile
// time — no runtime String building, and the sprite is stored once.
//
// Same approach as webpage.h: icons are inline SVG, so the pages need no
// network access. That matters most here, since the MQTT page is served
// in AP mode where there is no internet by definition.

#define PAGE_ICON_CSS \
    ".ic{width:1em;height:1em;display:inline-block;vertical-align:-.125em;flex:none;" \
    "fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}" \
    ".ic .f,symbol.f *{fill:currentColor;stroke:none}"

